from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
left_drive_motor = Motor(Port.B, Direction.COUNTERCLOCKWISE)
right_drive_motor = Motor(Port.F, Direction.CLOCKWISE)
drive_base_2 = DriveBase(left_drive_motor, right_drive_motor, 100, 114)


# The main program starts here.
drive_base_2.straight(500, then=Stop.BRAKE)
